// ════════════════════════════════════════════════════════════════════
//  HTF PO3 + RSI Divergence — V2 MTF REAL (port MQL5 Hammad Dilber v1.07)
//  Engine: Custom Script V6.4 (security() + parameter + cache)
//
//  PERBEDAAN vs port V6.2 (yang aproksimasi RSI di chart M1):
//    - RSI benar-benar dihitung DI H1 lewat security() — pivot dan
//      divergensi pakai data H1 asli (closed bars, no-lookahead).
//    - Parameter (htf, rsiLen, lbL, lbR, level, win) dirujuk LANGSUNG
//      dalam ekspresi security() — fitur V6.4. Ganti htf = "H4"/"D1"
//      tinggal ubah 1 var — cache key ikut berubah otomatis.
//    - Hasil security() di-cache per (ekspresi + NILAI param + TF):
//      recompute hanya saat H1 close baru; tick M1 = cache hit.
//      (RenderSettings → "V6.3/V6.4 Cache" stats.)
//
//  CATATAN DESAIN — jendela pivot DISKALAKAN ke satuan jam:
//    r = security("H1", ...) di chart M1 berbentuk STEP (nilai per jam).
//    Rumus MQL5 lbLeft/lbRight=5 BAR H1 = 5 JAM di chart M1 → jendela
//    pivot di-chart M1 harus lbL*60 / lbR*60 bar M1, bukan 6/5 — kalau
//    tidak, setiap batas jam jadi "pivot" (degenerate). Skala ini menjaga
//    semantik MQL5 asli: pivot = ekstrem H1 terkonfirmasi 5 jam kemudian.
//
//  Bagian yang di-port 1:1 dari MQL5:
//    - Pivot low/high di RSI (kiri 5, kanan 5 — satuan H1)
//    - Bullish div: price LOWER low + RSI HIGHER low → garis lime
//    - Bearish div: price HIGHER high + RSI LOWER high → garis merah
//    - BUY/SELL arrow di candle divergence, offset = ATR(14) * 0.5
//    - Filter arrow: RSI <= 45 (buy) / RSI >= 55 (sell)
//    - Label "Bull Div"/"Bear Div" di ujung garis
//
//  Backtest safety (no-lookahead): security() default memakai bar H1
//    yang SUDAH CLOSED — nilai saat jam berjalan = H1 closed sebelumnya
//    (tidak bocor data masa depan). Replay/scrub auto di-invalidate.
// ════════════════════════════════════════════════════════════════════
overlay()

// ── Setting (padanan input MQL5 — semuanya jadi parameter V6.4) ──
htf       = "H1"     // timeframe HTF: M5/M15/H1/H4/D1 (symbol-prefixed juga ok)
rsiLen    = 14       // InpRsiLen
rsiBuyLv  = 45.0     // InpRsiBuyLevel  — buy hanya kalau RSI <= ini
rsiSellLv = 55.0     // InpRsiSellLevel — sell hanya kalau RSI >= ini
lbL       = 5        // lbLeft  MQL5 (satuan BAR H1)
lbR       = 5        // lbRight MQL5 (satuan BAR H1)
win       = 1440     // panjang scan pivot (bar M1 ≈ 24 jam). Naikkan utk
                    // garis lebih jauh ke belakang (300 jam = 18000).

// ── RSI HTF (V6.4: parameter dirujuk dalam security(), di-cache) ──
r   = security(htf, rsi(close, rsiLen))
gap = atr(14) * 0.5

// ── Pivot mask di RSI H1 — jendela diskalakan jam→bar M1 ──
// kiri : r == min(r, lbL+1 jam)     → r == llv(r, (lbL + 1) * 60)
// kanan: r <  min(r, lbR jam depan) → r < ref(llv(r, lbR * 60), -lbR * 60)
// Pivot terkonfirmasi lbR JAM kemudian — sama kayak MQL5.
isPL = r == llv(r, (lbL + 1) * 60) and r < ref(llv(r, lbR * 60), -lbR * 60)
isPH = r == hhv(r, (lbL + 1) * 60) and r > ref(hhv(r, lbR * 60), -lbR * 60)

// ── State pivot memory (padanan plPriceMem / phPriceMem MQL5) ──
plX = 0
plY = 0
plR = 0
phX = 0
phY = 0
phR = 0
sigBuy  = 0
sigSell = 0

// ── Scan chronological — state machine persis OnCalculate MQL5 ──
for i in range(bar_index - win, bar_index + 1):
    // Bullish: pivot low baru, harga LL, RSI HL
    if at(isPL, i):
        if plX > 0 and at(low, i) < plY and at(r, i) > plR:
            segB = [[canvas.bar_x(plX), canvas.price_y(plY)], [canvas.bar_x(i), canvas.price_y(at(low, i))]]
            canvas.polyline(segB, color=lime, width=2)
            if at(r, i) <= rsiBuyLv:
                sigBuy = sigBuy + (bar_index == i)
        plX = i
        plY = at(low, i)
        plR = at(r, i)
    // Bearish: pivot high baru, harga HH, RSI LH
    if at(isPH, i):
        if phX > 0 and at(high, i) > phY and at(r, i) < phR:
            segS = [[canvas.bar_x(phX), canvas.price_y(phY)], [canvas.bar_x(i), canvas.price_y(at(high, i))]]
            canvas.polyline(segS, color=red, width=2)
            if at(r, i) >= rsiSellLv:
                sigSell = sigSell + (bar_index == i)
        phX = i
        phY = at(high, i)
        phR = at(r, i)

// ── Panah sinyal di candle divergence (offset ATR, kayak DrawSignalArrow) ──
if sigBuy > 0:
    arrow(buy, price=low - gap, color=green, size=10)
    label(bar_index, low, "Bull Div", color=lime, size=9)
if sigSell > 0:
    arrow(sell, price=high + gap, color=red, size=10)
    label(bar_index, high, "Bear Div", color=red, size=9)
